/**
 * Stanford's accessible-entrance list, and matching a spoken or typed
 * destination against it.
 *
 * The data is generated by `scripts/build-buildings.ts` and committed, so this
 * lookup is instant and works offline — which matters, because the alternative
 * (a geocoder round trip) is the slowest and least reliable part of the app.
 *
 * Matching is deliberately conservative. A wrong match here is worse than no
 * match: it would walk someone to the wrong building and then read them the
 * wrong entrance description with full confidence. So a match has to clear a
 * score threshold, and the matched name is always shown and spoken back so the
 * user can catch it.
 */

import type { BuildingInfo } from '../types';
// The import attribute is required by Node's ESM loader and ignored by Vite's.
// Keeping it means this module can be imported by a plain `node` script as well
// as by the bundler, which is what makes the matching logic testable.
import data from '../data/buildings.json' with { type: 'json' };

interface BuildingsFile {
  source: string;
  coordinateSources: string;
  generated: string;
  buildings: BuildingInfo[];
}

const file = data as BuildingsFile;

/** Where the data came from, shown in the UI so the advice is attributable. */
export const BUILDINGS_SOURCE = file.source;
export const BUILDINGS_GENERATED = file.generated;

export const buildings: readonly BuildingInfo[] = file.buildings;

/**
 * Words that carry no identifying information in a destination phrase. Dropping
 * them stops "the Green Library building" from scoring worse than "Green
 * Library", and stops a shared word like "center" from matching on its own.
 */
const STOP_WORDS = new Set([
  'the', 'a', 'an', 'of', 'at', 'in', 'on', 'to', 'and', '&',
  'building', 'bldg', 'hall', 'center', 'centre', 'entrance', 'main',
  'stanford', 'university', 'campus',
]);

/** Fold case, punctuation and spacing so "ST. JOHN'S" and "st johns" agree. */
function normalize(text: string): string {
  return text
    .toLowerCase()
    .replace(/[.,/#!$%^*;:{}=\-_`~()'"]/g, ' ')
    .replace(/&/g, ' and ')
    .replace(/\s+/g, ' ')
    .trim();
}

function contentWords(text: string): string[] {
  return normalize(text)
    .split(' ')
    .filter((word) => word.length > 1 && !STOP_WORDS.has(word));
}

/**
 * Pre-computed search keys. Built once at module load: 178 buildings is small
 * enough that scoring them all on every keystroke is free, but re-normalising
 * them every time is not.
 */
const indexed = buildings.map((building) => ({
  building,
  normalizedName: normalize(building.name),
  normalizedAddress: normalize(building.address),
  nameWords: contentWords(building.name),
}));

/**
 * The minimum score a match must reach. Tuned so that a full building name or a
 * distinctive word ("Dinkelspiel", "Windhover") matches, while a generic phrase
 * ("the library", "a dining hall") does not — those fall through to the
 * photo-and-geocoder path, which is honest about not knowing.
 */
const MATCH_THRESHOLD = 0.55;

/**
 * A match must beat the runner-up by this much to be acted on.
 *
 * Clearing the threshold is not enough on its own. "The library" scores well
 * against Lathrop Library — and just as well against Green Library, and the
 * law library. Picking the highest of those is picking arbitrarily, and the
 * user would have no way to tell. Where the field is that close, the honest
 * answer is no match: the app then says so, and falls back to the geocoder and
 * the camera instead of walking someone to a building chosen by rounding.
 *
 * A match on the name or address itself skips this check — "Green Library"
 * naming "Green Library - East" is not ambiguity, it is the answer.
 */
const AMBIGUITY_MARGIN = 0.08;

export interface BuildingMatch {
  building: BuildingInfo;
  /** 0–1. Only matches at or above the threshold are returned. */
  score: number;
}

/**
 * Score one building against a normalized query.
 *
 * `named` distinguishes the two ways a query can score well, which matter
 * differently: the query either reproduced the building's name or address
 * (`named`), or it merely shares words with it. Only the first is safe to act
 * on when another building scores nearly as well — see AMBIGUITY_MARGIN.
 */
function score(
  query: string,
  queryWords: string[],
  entry: (typeof indexed)[number],
): { value: number; named: boolean } {
  const { normalizedName, normalizedAddress, nameWords } = entry;

  // Exact name, or the query is the name with something tacked on ("Green
  // Library entrance"), or the other way round.
  if (query === normalizedName) return { value: 1, named: true };

  if (query.includes(normalizedName) || normalizedName.includes(query)) {
    // Favour the closer length match, so "Green Library" prefers "GREEN
    // LIBRARY" over "GREEN LIBRARY - EAST" but still matches both.
    const ratio =
      Math.min(query.length, normalizedName.length) /
      Math.max(query.length, normalizedName.length);
    return { value: 0.75 + 0.25 * ratio, named: true };
  }

  // The street address, which is how the sheet is keyed and how people often
  // describe a Stanford building ("450 Jane Stanford Way").
  if (normalizedAddress && query.length > 6 && normalizedAddress.includes(query)) {
    return { value: 0.9, named: true };
  }

  if (queryWords.length === 0 || nameWords.length === 0) return { value: 0, named: false };

  // Otherwise: how much of the query's content is accounted for by this name,
  // and how much of the name the query covers. Requiring both keeps a one-word
  // overlap with a long name from winning on its own.
  const shared = queryWords.filter((word) =>
    nameWords.some((nameWord) => nameWord.startsWith(word) || word.startsWith(nameWord)),
  ).length;

  if (shared === 0) return { value: 0, named: false };

  const queryCoverage = shared / queryWords.length;
  const nameCoverage = shared / nameWords.length;

  return { value: 0.7 * queryCoverage + 0.3 * nameCoverage, named: false };
}

/**
 * Best Stanford building for what the user said, or null if nothing is a
 * confident match. Null is a normal outcome, not a failure: the app then works
 * from the geocoder and the camera, exactly as it did before this data existed.
 */
export function matchBuilding(destination: string): BuildingMatch | null {
  const query = normalize(destination);
  if (query.length < 3) return null;

  const queryWords = contentWords(destination);

  let best: (BuildingMatch & { named: boolean }) | null = null;
  let runnerUp = 0;

  for (const entry of indexed) {
    const { value, named } = score(query, queryWords, entry);
    if (value < MATCH_THRESHOLD) continue;

    if (!best || value > best.score) {
      runnerUp = Math.max(runnerUp, best?.score ?? 0);
      best = { building: entry.building, score: value, named };
    } else if (value > runnerUp) {
      runnerUp = value;
    }
  }

  if (!best) return null;

  // Naming a building stands on its own; describing one has to be decisive.
  if (!best.named && best.score - runnerUp < AMBIGUITY_MARGIN) return null;

  return { building: best.building, score: best.score };
}

/**
 * Buildings whose name begins with, or contains, what has been typed — for the
 * destination field's suggestion list. Capped because a datalist of 178 entries
 * is unusable with a screen reader.
 */
export function suggestBuildings(partial: string, limit = 8): BuildingInfo[] {
  const query = normalize(partial);
  if (!query) return [];

  const starts: BuildingInfo[] = [];
  const contains: BuildingInfo[] = [];

  for (const entry of indexed) {
    if (entry.normalizedName.startsWith(query)) starts.push(entry.building);
    else if (entry.normalizedName.includes(query)) contains.push(entry.building);
    if (starts.length >= limit) break;
  }

  return [...starts, ...contains].slice(0, limit);
}

/**
 * Title-case a Stanford building name for display and speech. The sheet stores
 * them shouted ("ARRILLAGA FAMILY DINING COMMONS"), and a screen reader or a
 * speech synthesiser will often spell out or shout an all-caps string.
 */
export function displayName(name: string): string {
  return name
    .toLowerCase()
    .replace(/\b[a-z]/g, (letter) => letter.toUpperCase())
    // Roman-ish numerals and compass initialisms that should stay capitalised.
    .replace(/\b(Ii|Iii|Iv|Vi|Vii|Viii|Ix|Xi|Xii)\b/g, (match) => match.toUpperCase());
}
